const item = $input.first();
const telegramText = $('Telegram Trigger').item.json.message.text || '';
const idea = telegramText.replace(/^\/search\s+/i, '').trim();

const isSerp = !!(item.json.organic_results || item.json.text_blocks || item.json.references);

let serpContext = '';
if (isSerp) {
  const blocks = item.json.text_blocks || [];
  const refs = item.json.references || [];
  const organic = (item.json.organic_results || []).map(r => ({ title: r.title, snippet: r.snippet }));
  const all = [...blocks, ...refs, ...organic].slice(0, 6);
  serpContext = all.map(b => {
    const title = b.title || '';
    const snippet = b.snippet || b.text || b.body || '';
    return title ? `**${title}**\n${snippet}` : snippet;
  }).filter(Boolean).join('\n\n');
}

return [{ json: { idea, serp_context: serpContext, has_serp: isSerp } }];

const items = $input.all();
const personaOutputs = items.map(i => i.json.output || '').join('

---

');
const prep = $('Code: Prepare Context').first().json;
return [{ json: { idea: prep.idea, serp_context: prep.serp_context || '', persona_outputs: personaOutputs } }];

const item = $input.first();
let raw = (item.json.output || '').trim();
const fence = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (fence) raw = fence[1].trim();
const prep = $('Code: Aggregate Personas').first().json;
try {
  const parsed = JSON.parse(raw);
  return [{ json: { ...parsed, idea: prep.idea, persona_outputs: prep.persona_outputs } }];
} catch(_) {
  return [{ json: {
    _parse_error: true,
    idea: prep.idea,
    persona_outputs: prep.persona_outputs,
    one_liner: 'See raw output',
    original_summary: prep.idea,
    refined_idea: raw,
    next_actions: [],
    critiques_upheld: [],
    critiques_dismissed: [],
    confidence: 'unknown'
  } }];
}

const d = $input.first().json;
const today = DateTime.now().toFormat('yyyy-MM-dd');
const slug = (d.one_liner || d.original_summary || 'brainstorm')
  .toLowerCase().replace(/[^a-z0-9\s-]/g, '').trim()
  .replace(/\s+/g, '-').substring(0, 80);
const filename = `${today}-${slug}.md`;

const nextActions = Array.isArray(d.next_actions)
  ? d.next_actions.map(a => `- [ ] ${a}`).join('\n')
  : '';
const upheld = Array.isArray(d.critiques_upheld)
  ? d.critiques_upheld.map(c => `- ${c}`).join('\n')
  : '';
const dismissed = Array.isArray(d.critiques_dismissed)
  ? d.critiques_dismissed.map(c => `- ${c}`).join('\n')
  : '';
const nextList = Array.isArray(d.next_actions)
  ? d.next_actions.map((a, i) => `${i + 1}. ${a}`).join('\n')
  : '';

const content = `---
title: "${(d.original_summary || '').replace(/"/g, "'")}"
type: brainstorm
created: ${today}
updated: ${today}
confidence: "${d.confidence || 'unknown'}"
one_liner: "${(d.one_liner || '').replace(/"/g, "'")}"
---

## Raw Idea
${d.idea || ''}

## Refined Idea
${d.refined_idea || ''}

## One-Liner
${d.one_liner || ''}

## Critiques That Landed
${upheld}

## Critiques Dismissed
${dismissed}

## Next Actions
${nextActions}

---

## Full Persona Debate

${d.persona_outputs || ''}`;

const telegramReply = `💡 *${d.one_liner || d.original_summary || ''}*\n\n${(d.refined_idea || '').substring(0, 600)}\n\n*Next steps:*\n${nextList}\n\n_Confidence: ${d.confidence || 'unknown'} · Saved to vault_`;

return [{ json: { filename, content, telegram_reply: telegramReply } }];
